class SlavicBaseLocale(Locale):
    timeframes: ClassVar[Mapping[TimeFrameLiteral, Union[str, Mapping[str, str]]]]

    def _format_timeframe(self, timeframe: TimeFrameLiteral, delta: int) -> str:
        """Format a timeframe with proper Slavic pluralization rules."""
        form = self.timeframes[timeframe]
        delta = abs(delta)

        if isinstance(form, Mapping):
            # Ensure all required keys exist for Slavic pluralization
            required_keys = {"singular", "dual", "plural"}
            if not required_keys.issubset(form.keys()):
                # Fallback to string representation if keys are missing
                return str(form)

            # Apply Slavic pluralization rules with error handling
            try:
                mod10 = delta % 10
                mod100 = delta % 100

                if mod10 == 1 and mod100 != 11:
                    form = form["singular"]
                elif 2 <= mod10 <= 4 and (mod100 < 10 or mod100 >= 20):
                    form = form["dual"]
                else:
                    form = form["plural"]
            except ZeroDivisionError:
                # Handle any unexpected division by zero (shouldn't happen with modulo)
                form = form["plural"]
            except Exception:
                # Fallback to plural form for any other unexpected errors
                form = form["plural"]

        # Format the string with delta value
        try:
            return form.format(delta)
        except Exception:
            # Ultimate fallback
            return f"{delta} {timeframe}"
EOF
